import React, { useState, useEffect } from 'react';
import { Edit3, CheckCircle, Zap, User, BookOpen, Code, Target, Award, Camera, Activity, Eye, Network } from 'lucide-react';

const skillOptions = ['React', 'Python', 'Java', 'Machine Learning', 'SQL', 'Node.js', 'Data Analysis', 'Product Management', 'UI/UX Design', 'System Design', 'AWS', 'Docker'];
const interestOptions = ['FinTech', 'Product Management', 'Data Science', 'Software Engineering', 'AI/ML', 'Consulting', 'Design', 'DevOps', 'Research', 'Entrepreneurship'];
const societyOptions = ['None', 'UCS - University Coding Society', 'UDT - University Design Team', 'ULC - University Literary Club'];

const generateBio = async (name, branch, year, skills, interests) => {
  await new Promise(r => setTimeout(r, 1800));
  return `I'm ${name}, a ${year} ${branch.includes('Batch') ? 'graduate' : 'student'} with a strong foundation in ${skills.slice(0, 2).join(' and ')}. I'm passionate about building innovative solutions at the intersection of technology and ${interests[0] || 'business'}. Exploring opportunities in ${interests.slice(0, 2).join(' and ')}, I thrive in collaborative environments where I can apply my analytical thinking to real-world problems.`;
};

export default function Profile({ role, user, setUser }) {
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(user?.name || (role === 'alumni' ? 'Alumni User' : 'Student User'));
  const [branch, setBranch] = useState(user?.branch || 'B.Tech Computer Science Engineering');
  const [year, setYear] = useState(user?.year || (role === 'alumni' ? 'Batch 2020' : '3rd Year'));
  const [bio, setBio] = useState(user?.bio || (role === 'alumni'
    ? `${user?.role_title || 'Professional'} at ${user?.company || 'Company'}. Passionate about mentoring students from my alma mater.`
    : 'Add your bio or generate one using AI below.'));
  const [skills, setSkills] = useState(user?.skills || ['React', 'Python', 'SQL']);
  const [interests, setInterests] = useState(user?.interests || ['Product Management', 'FinTech']);
  const [society, setSociety] = useState(user?.society || 'None');
  const [generating, setGenerating] = useState(false);
  const [saved, setSaved] = useState(false);
  const [visible, setVisible] = useState(false);
  useEffect(() => { setTimeout(() => setVisible(true), 100); }, []);

  const handleGenBio = async () => {
    setGenerating(true);
    setBio(await generateBio(name, branch, year, skills, interests));
    setGenerating(false);
  };

  const handleSave = () => {
    setEditing(false); setSaved(true);
    if (setUser) setUser(prev => ({ ...prev, name, branch, year, bio, skills, interests, society }));
    setTimeout(() => setSaved(false), 3000);
  };

  const toggleSkill = s => setSkills(p => p.includes(s) ? p.filter(x => x !== s) : [...p, s]);
  const toggleInterest = i => setInterests(p => p.includes(i) ? p.filter(x => x !== i) : [...p, i]);
  const completion = Math.min(100, [name, branch, year, bio.length > 50, skills.length > 0, interests.length > 0, society !== 'None'].filter(Boolean).length * 14);

  return (
    <div style={{ padding: '20px 40px 60px', maxWidth: 1100, margin: '0 auto', opacity: visible ? 1 : 0, transform: visible ? 'none' : 'translateY(20px)', transition: 'all 0.6s ease' }}>
      
      {/* === HEADER & BANNER === */}
      <div style={{ position: 'relative', marginBottom: 40 }}>
        {/* Cover Banner */}
        <div style={{ height: 180, borderRadius: 24, background: 'linear-gradient(135deg, rgba(245,166,35,0.15), rgba(77,166,255,0.08))', border: '1px solid rgba(255,255,255,0.05)', position: 'relative', overflow: 'hidden' }}>
          <div style={{ position: 'absolute', top: -50, right: -50, width: 300, height: 300, background: 'radial-gradient(circle, rgba(245,166,35,0.2), transparent 70%)', filter: 'blur(40px)', animation: 'float 6s ease-in-out infinite' }} />
          <div style={{ position: 'absolute', bottom: -50, left: '20%', width: 250, height: 250, background: 'radial-gradient(circle, rgba(77,166,255,0.15), transparent 70%)', filter: 'blur(30px)', animation: 'float 8s ease-in-out infinite reverse' }} />
          
          {editing && (
            <button style={{ position: 'absolute', top: 20, right: 20, padding: '8px 16px', borderRadius: 10, background: 'rgba(0,0,0,0.5)', border: '1px solid rgba(255,255,255,0.1)', color: 'var(--white)', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6, backdropFilter: 'blur(10px)', cursor: 'pointer' }}>
              <Camera size={14} /> Edit Cover
            </button>
          )}
        </div>

        {/* Avatar & Controls Overlapping */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', padding: '0 40px', marginTop: -60 }}>
          <div style={{ display: 'flex', alignItems: 'flex-end', gap: 24 }}>
            <div style={{ width: 120, height: 120, borderRadius: '50%', background: 'linear-gradient(135deg, var(--gold), #e8880a)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 48, color: '#07091a', border: '6px solid var(--navy)', boxShadow: '0 10px 40px rgba(245,166,35,0.3)', position: 'relative', zIndex: 2 }}>
              {name[0]?.toUpperCase()}
              {editing && (
                <div style={{ position: 'absolute', bottom: 0, right: 0, width: 36, height: 36, borderRadius: '50%', background: 'var(--navy)', border: '2px solid var(--gold)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
                  <Camera size={14} color="var(--gold)" />
                </div>
              )}
            </div>
            
            <div style={{ paddingBottom: 10 }}>
              {editing ? (
                <input value={name} onChange={e => setName(e.target.value)} style={{ padding: '8px 12px', borderRadius: 10, border: '1px solid var(--gold-border)', background: 'var(--navy-card)', color: 'var(--white)', fontSize: 24, fontWeight: 800, outline: 'none', fontFamily: 'var(--font-display)', marginBottom: 8, width: 300, boxShadow: '0 10px 30px rgba(0,0,0,0.5)' }} />
              ) : (
                <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 32, fontWeight: 800, color: 'var(--white)', marginBottom: 4 }}>{name}</h1>
              )}
              {editing ? (
                <div style={{ display: 'flex', gap: 10 }}>
                  <input value={branch} onChange={e => setBranch(e.target.value)} style={{ padding: '6px 12px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.1)', background: 'var(--navy-card)', color: 'var(--text-secondary)', fontSize: 14, outline: 'none', width: 220 }} />
                  <input value={year} onChange={e => setYear(e.target.value)} style={{ padding: '6px 12px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.1)', background: 'var(--navy-card)', color: 'var(--text-secondary)', fontSize: 14, outline: 'none', width: 100 }} />
                </div>
              ) : (
                <div style={{ color: 'var(--text-secondary)', fontSize: 15 }}>{branch} • <span style={{ color: 'var(--gold)' }}>{year}</span></div>
              )}
            </div>
          </div>

          <div style={{ paddingBottom: 10, display: 'flex', gap: 12 }}>
            {saved && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '12px 18px', borderRadius: 12, background: 'rgba(34,212,94,0.1)', color: 'var(--success)', fontSize: 14, fontWeight: 700, border: '1px solid rgba(34,212,94,0.2)', animation: 'fadeUp 0.3s ease' }}>
                <CheckCircle size={16} /> Profile Saved!
              </div>
            )}
            <button onClick={() => editing ? handleSave() : setEditing(true)} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '12px 24px', borderRadius: 12, background: editing ? 'linear-gradient(135deg, var(--gold), #e8880a)' : 'rgba(255,255,255,0.05)', color: editing ? '#07091a' : 'var(--white)', fontWeight: 700, fontSize: 14, border: editing ? 'none' : '1px solid rgba(255,255,255,0.1)', transition: 'all 0.3s', cursor: 'pointer', boxShadow: editing ? '0 10px 30px rgba(245,166,35,0.3)' : 'none' }}
              onMouseEnter={e => { if(!editing) { e.currentTarget.style.background = 'rgba(255,255,255,0.1)'; } else { e.currentTarget.style.transform = 'translateY(-2px)'; } }}
              onMouseLeave={e => { if(!editing) { e.currentTarget.style.background = 'rgba(255,255,255,0.05)'; } else { e.currentTarget.style.transform = 'none'; } }}>
              {editing ? <><CheckCircle size={16} /> Save Changes</> : <><Edit3 size={16} /> Edit Profile</>}
            </button>
          </div>
        </div>
      </div>

      {/* === 2-COLUMN GRID === */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 320px', gap: 24, alignItems: 'start' }}>
        
        {/* LEFT COLUMN: Main Info */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          
          {/* Bio */}
          <div style={{ background: 'var(--navy-card)', borderRadius: 24, border: generating ? '1px solid var(--gold)' : '1px solid rgba(255,255,255,0.07)', padding: 32, transition: 'all 0.3s', boxShadow: generating ? '0 0 30px rgba(245,166,35,0.1)' : 'none' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <div style={{ width: 36, height: 36, borderRadius: 10, background: 'rgba(245,166,35,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <BookOpen size={18} color="var(--gold)" />
                </div>
                <h2 style={{ fontFamily: 'var(--font-display)', fontWeight: 800, color: 'var(--white)', fontSize: 20 }}>About</h2>
              </div>
              <button onClick={handleGenBio} disabled={generating} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 16px', borderRadius: 10, border: '1px solid var(--gold-border)', background: 'var(--gold-dim)', color: 'var(--gold)', fontSize: 13, fontWeight: 700, opacity: generating ? 0.7 : 1, cursor: generating ? 'not-allowed' : 'pointer', transition: 'all 0.2s' }} onMouseEnter={e => !generating && (e.currentTarget.style.background = 'rgba(245,166,35,0.2)')} onMouseLeave={e => !generating && (e.currentTarget.style.background = 'var(--gold-dim)')}>
                <Zap size={14} />
                {generating ? 'AI is writing...' : 'AI Rewrite ✨'}
              </button>
            </div>

            {generating ? (
              <div style={{ padding: '24px', background: 'var(--navy-2)', borderRadius: 16, border: '1px solid var(--gold-border)' }}>
                <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
                  {[1, 2, 3].map(i => <div key={i} style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--gold)', animation: `pulse-gold ${0.5 + i * 0.2}s infinite` }} />)}
                </div>
                <div style={{ height: 12, background: 'linear-gradient(90deg, var(--navy-3), var(--gold-dim), var(--navy-3))', backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite', borderRadius: 6, marginBottom: 10 }} />
                <div style={{ height: 12, background: 'linear-gradient(90deg, var(--navy-3), var(--gold-dim), var(--navy-3))', backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite 0.2s', borderRadius: 6, width: '85%', marginBottom: 10 }} />
                <div style={{ height: 12, background: 'linear-gradient(90deg, var(--navy-3), var(--gold-dim), var(--navy-3))', backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite 0.4s', borderRadius: 6, width: '60%' }} />
              </div>
            ) : editing ? (
              <textarea value={bio} onChange={e => setBio(e.target.value)} rows={5} style={{ width: '100%', padding: '16px', borderRadius: 16, border: '1px solid rgba(255,255,255,0.1)', background: 'var(--navy-2)', color: 'var(--text-primary)', fontSize: 15, outline: 'none', lineHeight: 1.7, resize: 'vertical' }} />
            ) : (
              <p style={{ fontSize: 15, color: 'var(--text-secondary)', lineHeight: 1.8, margin: 0 }}>{bio}</p>
            )}
          </div>

          {/* Skills */}
          <div style={{ background: 'var(--navy-card)', borderRadius: 24, border: '1px solid rgba(255,255,255,0.07)', padding: 32 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
              <div style={{ width: 36, height: 36, borderRadius: 10, background: 'rgba(77,166,255,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Code size={18} color="#4da6ff" />
              </div>
              <h2 style={{ fontFamily: 'var(--font-display)', fontWeight: 800, color: 'var(--white)', fontSize: 20 }}>Top Skills</h2>
            </div>
            <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
              {skillOptions.map(s => {
                const active = skills.includes(s);
                return (
                  <button key={s} onClick={() => editing && toggleSkill(s)} style={{ padding: '10px 18px', borderRadius: 20, border: `1px solid ${active ? '#4da6ff' : 'rgba(255,255,255,0.1)'}`, background: active ? 'rgba(77,166,255,0.1)' : 'var(--navy-2)', color: active ? '#4da6ff' : 'var(--text-secondary)', fontSize: 14, fontWeight: active ? 700 : 500, cursor: editing ? 'pointer' : 'default', transition: 'all 0.2s', opacity: editing || active ? 1 : 0.5 }}
                    onMouseEnter={e => { if (editing) { e.currentTarget.style.transform = 'translateY(-2px)'; e.currentTarget.style.borderColor = '#4da6ff'; } }}
                    onMouseLeave={e => { if (editing) { e.currentTarget.style.transform = 'none'; e.currentTarget.style.borderColor = active ? '#4da6ff' : 'rgba(255,255,255,0.1)'; } }}>
                    {active && '✓ '}{s}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Interests */}
          <div style={{ background: 'var(--navy-card)', borderRadius: 24, border: '1px solid rgba(255,255,255,0.07)', padding: 32 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
              <div style={{ width: 36, height: 36, borderRadius: 10, background: 'rgba(168,139,250,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Target size={18} color="#a78bfa" />
              </div>
              <h2 style={{ fontFamily: 'var(--font-display)', fontWeight: 800, color: 'var(--white)', fontSize: 20 }}>Career Interests</h2>
            </div>
            <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
              {interestOptions.map(i => {
                const active = interests.includes(i);
                return (
                  <button key={i} onClick={() => editing && toggleInterest(i)} style={{ padding: '10px 18px', borderRadius: 20, border: `1px solid ${active ? '#a78bfa' : 'rgba(255,255,255,0.1)'}`, background: active ? 'rgba(168,139,250,0.1)' : 'var(--navy-2)', color: active ? '#a78bfa' : 'var(--text-secondary)', fontSize: 14, fontWeight: active ? 700 : 500, cursor: editing ? 'pointer' : 'default', transition: 'all 0.2s', opacity: editing || active ? 1 : 0.5 }}
                    onMouseEnter={e => { if (editing) { e.currentTarget.style.transform = 'translateY(-2px)'; e.currentTarget.style.borderColor = '#a78bfa'; } }}
                    onMouseLeave={e => { if (editing) { e.currentTarget.style.transform = 'none'; e.currentTarget.style.borderColor = active ? '#a78bfa' : 'rgba(255,255,255,0.1)'; } }}>
                    {active && '✓ '}{i}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Sidebar Stats */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          
          {/* Profile Completion */}
          <div style={{ background: 'var(--navy-card)', borderRadius: 24, border: '1px solid rgba(255,255,255,0.07)', padding: '24px', position: 'relative', overflow: 'hidden' }}>
            <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 4, background: 'linear-gradient(90deg, var(--gold), #ffc55a)' }} />
            <h3 style={{ fontSize: 14, fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 12 }}>Profile Strength</h3>
            <div style={{ display: 'flex', alignItems: 'flex-end', gap: 8, marginBottom: 16 }}>
              <span style={{ fontFamily: 'var(--font-display)', fontSize: 40, fontWeight: 800, color: 'var(--gold)', lineHeight: 1 }}>{completion}%</span>
              <span style={{ fontSize: 14, color: 'var(--success)', fontWeight: 600, paddingBottom: 6 }}>Awesome!</span>
            </div>
            <div style={{ height: 8, background: 'rgba(255,255,255,0.08)', borderRadius: 4, marginBottom: 12 }}>
              <div style={{ width: `${completion}%`, height: '100%', background: 'linear-gradient(90deg, var(--gold), #ffc55a)', borderRadius: 4, transition: 'width 0.5s ease', boxShadow: '0 0 10px rgba(245,166,35,0.5)' }} />
            </div>
            <p style={{ fontSize: 13, color: 'var(--text-muted)', lineHeight: 1.5, margin: 0 }}>Profiles with 80%+ completion are 5x more likely to secure mentorships.</p>
          </div>

          {/* Society */}
          <div style={{ background: 'var(--navy-card)', borderRadius: 24, border: '1px solid rgba(255,255,255,0.07)', padding: 24 }}>
            <h3 style={{ fontSize: 16, fontWeight: 700, color: 'var(--white)', marginBottom: 16, display: 'flex', alignItems: 'center', gap: 8 }}>
              <Award size={16} color="#fb923c" /> University Society
            </h3>
            {editing ? (
              <select value={society} onChange={e => setSociety(e.target.value)} style={{ width: '100%', padding: '12px 14px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.1)', background: 'var(--navy-2)', color: 'var(--text-primary)', fontSize: 14, outline: 'none', cursor: 'pointer' }}>
                {societyOptions.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            ) : (
              <div style={{ padding: '14px', background: society !== 'None' ? 'rgba(251,146,60,0.1)' : 'rgba(255,255,255,0.03)', border: `1px solid ${society !== 'None' ? 'rgba(251,146,60,0.3)' : 'rgba(255,255,255,0.07)'}`, borderRadius: 12, color: society !== 'None' ? '#fb923c' : 'var(--text-muted)', fontSize: 14, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 10 }}>
                {society !== 'None' ? '🏆' : ''} {society === 'None' ? 'Not part of any society' : society}
              </div>
            )}
          </div>

          {/* Quick Stats */}
          <div style={{ background: 'var(--navy-card)', borderRadius: 24, border: '1px solid rgba(255,255,255,0.07)', padding: 24 }}>
             <h3 style={{ fontSize: 16, fontWeight: 700, color: 'var(--white)', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 8 }}>
               <Activity size={16} color="#22d45e" /> Profile Activity
             </h3>
             <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
               <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                 <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: 'var(--text-secondary)', fontSize: 14 }}>
                   <Eye size={16} /> Profile Views
                 </div>
                 <div style={{ fontWeight: 800, color: 'var(--white)', fontSize: 16 }}>142</div>
               </div>
               <div style={{ height: 1, background: 'rgba(255,255,255,0.05)' }} />
               <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                 <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: 'var(--text-secondary)', fontSize: 14 }}>
                   <Network size={16} /> Connections
                 </div>
                 <div style={{ fontWeight: 800, color: 'var(--white)', fontSize: 16 }}>28</div>
               </div>
               <div style={{ height: 1, background: 'rgba(255,255,255,0.05)' }} />
               <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                 <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: 'var(--text-secondary)', fontSize: 14 }}>
                   <Target size={16} /> Mentor Matches
                 </div>
                 <div style={{ fontWeight: 800, color: 'var(--white)', fontSize: 16 }}>4</div>
               </div>
             </div>
          </div>

        </div>
      </div>
    </div>
  );
}
